root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign14-expression-equivalence-check';draft=root/'research/nine-sharing-sign14-expression-equivalence-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='a77edbf15ca63f1c555477a8247a229aa85bab7ceffb356bb46fa6b22c14053f' and sha(m)=='16cbff749c79d380a59db0ae85c5d091a2832c2c8bc9090ead86a7e7aa7b80ae';row,=json.loads(m.read_text())['rows'];name='Sign14ExpressionEquivalence';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='3e8787b2fa61fc9a01c265ed0c951d9ed4f8d1ff5f2c05e781452ec99bcf8c8b' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign14CurrentExpressionEval','DiophantineConsistency.Sign15CurrentExpressionEval','DiophantineConsistency.Sign14CurrentSeedIff'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('∃ w : Fin 14 → V, InternalZero Sign14CurrentExpression.expression w','∃ w : Fin 15 → V, InternalZero Sign15CurrentExpression.expression w','Sign14CurrentSeedIff.exists_same_input (1 : V)','Sign14CurrentExpression.eval_expression','Sign15CurrentExpression.eval_expression','Fin.cons_self_tail v','Fin.tail v'):assert t in s
