checks=[('reviews/nine-sharing-sign14-current-iff-terminal-independent/check.py','9a71449489db59cbdaa60b3aa5c00f1f6c3c376b01ed65cbe8a8fe4d174106e8'),('reviews/nine-sharing-sign14-expression-eval-terminal-independent/check.py','4e4e42a17bfdaca569da35ea60752aa257dae9622fb403b3df7b1257bc87b3ae'),('reviews/nine-sharing-sign15-expression-eval-terminal-independent/check.py','42e79cca1ee3d1a5aff6c0b061ff28b3cd4b1006b5d0a230b8d8f09199b388bf')]
